
/**
 * Awards And Cert Component组件交互
 * @constructor
 */

import AnniversaryCarousel from "../../anniversary-carousel";

export function AwardsAndCertComponent() {
    $(() => {
        if ($('.awards-and-cert-component').length > 0) {
            const $body = $('body');
            const $popupBox = $('.awards-and-cert-component .popup-box');

            $('.awards-and-cert-component .learn-more')
                .click(() => {
                    $popupBox.addClass('show-popup');
                    $body.addClass('non-scroll');
                })
            $('.awards-and-cert-component .icon-close,.awards-and-cert-component .popup-overlay')
                .click(() => {
                    $popupBox.removeClass('show-popup');
                    $body.removeClass('non-scroll');
                })

            // 移动端轮播
            if (window.outerWidth < 1024) {
                const $carousel = $('.awards-and-cert-carousel');
                const autoplayVal = $carousel.data('autoplay')
                const delayVal = $carousel.data('delay') * 1000;
                // eslint-disable-next-line no-new
                new AnniversaryCarousel({
                    el: '.awards-and-cert-carousel',
                    autoplay: autoplayVal,
                    delay: delayVal
                })
            }
        }
    })
}
