/**
 *  GA统计
 */
export function AboutUsGAEvent() {
    $(() => {
        /**
         * @description GTM事件处理
         * @param {*} params 参数传递
         */
        const aboutGAEvent = (params) => {
            window.dataLayer.push({ event_parameters: null });
            window.dataLayer.push({
                event: "ga4Event",
                event_name: "about_us_user_clicks",
                event_parameters: {
                    current_page: window.location.href, // current page url
                    ...params
                }
            });
        }

        // slide-swiper版块 Item统计
        $('.slide-swiper .swiper-slide').click(function () {
            const position =  $(this).data("swiper-slide-index")+1
            const itemTitle = $(this).find('.slide-title').text()
            const bkImg=$($(this).find('.slide-image')).css('backgroundImage').replace('url(','').replace(')','');
            const link =$(this).find('.btn-link').data("link")
            //图片名称
            const bkSrc = bkImg.substr(bkImg.lastIndexOf("/") + 1);
            const module=itemTitle ? itemTitle : (bkSrc ? bkSrc : "Banner")
            const params = {
                module: module,
                position: position
            }
            if(link){
                params.link=link
            }
            aboutGAEvent(params);
        })

        // Anchor Nav版块 Item统计
        $('.anchor-nav-component li').click(function () {
            const itemTitle = $(this).text();
            const params = {
                module: "directory",
                position: itemTitle // 填充内容text
            }
            aboutGAEvent(params);
        })

        // awards-and-cert-component版块 Item统计
        $('.awards-and-cert-component .learn-more').click(function () {
            const $awardsComp = $('.awards-and-cert-component');
            const $moduleName = $awardsComp.prev('.common-title-component').find('.title').text() || 'Medium Display';
            const itemTitle = $(this).text();
            const params = {
                module: $moduleName,
                button_name: itemTitle // 填充内容text
            }
            aboutGAEvent(params);
        })

        // Safety First Component版块 Item统计
        $('.safety-first-component .tab-list li').click(function () {
            const $safeComp = $('.safety-first-component');
            const $moduleName = $safeComp.prev('.common-title-component').find('.title').text() || 'Brand Display';
            const itemTitle = $(this).text()?.trim();
            const params = {
                module: $moduleName,
                position: itemTitle // 填充内容text
            }
            aboutGAEvent(params);
        })

        // Time Line Component版块 Item统计
        //点击左右箭头
        var moduleText=$('.time-line-component .time-line-title').text();
        $('.time-line-component .custom-arrow').click(function () {
            const arrowButton = $(this).hasClass("swiper-button-prev") ? "left_button": "right_button"
            const params = {
                module: moduleText,
                button_name: arrowButton // 填充内容text
            }
            aboutGAEvent(params);
        })
        //点击年份
        $('.time-line-component .year-list li').click(function () {
            const yearButton = $(this).find("span").eq(1).text()
            const params = {
                module: moduleText,
                button_name: yearButton // 填充内容text
            }
            aboutGAEvent(params);
        })

    })
}
