/**
 * 公共标题组件
 */
export function CommonTitleComponent() {
    $(function () {
        // 公共标题组件
        if ($('.common-title-component').length > 0) {

            // 锚点定位
            const currAnchorID = window.location.hash;
            if (currAnchorID) {
                $('html, body').animate({
                    scrollTop: $(`${currAnchorID}`).offset().top - 50
                }, "slow");
            }

            // 副标题内 捐赠标识icon替换
            $('.common-title-box').each(function () {
                const $subtitle = $(this).find('.subtitle');
                const currTxt = $subtitle.data('txt');
                if (currTxt) {
                    const endTxt = currTxt.replaceAll('${heart}', '<i class="icon-donation"></i>');
                    $subtitle.html(endTxt)
                }
            })
        }
    })
}
