/**
 * 新版时间轴组件
 */
export function TimeLineComponent() {
    $(() => {
        const $timeLine = $('.time-line-component');
        if ($timeLine.length > 0) {
            $timeLine.each(function (index) {
                $(this).addClass(`time-line-component-${index + 1}`);
                const $currSwiper = $(this).find('.time-line-carousel');

                // 轮播图张数
                const total = $currSwiper.data('total') || 0;
                if (total <= 1) {
                    return;
                }

                // 是否自动轮播
                const isAutoplay = $currSwiper.data('autoplay');
                // 单张轮播图停留时长
                const delayVal = $currSwiper.data('delay') * 1000;

                // 年份轴线
                let viewNum = 6;
                if (window.outerWidth < 1024) {
                    viewNum = 3;
                }
                const thumbsSwiper = new Swiper(`.time-line-component-${index + 1} .year-line`, {
                    spaceBetween: 0,
                    slidesPerView: viewNum,
                    watchSlidesVisibility: true, // 防止不可点击
                    freeMode: true,
                    watchSlidesProgress: true,
                    initialSlide: total
                });

                let swiperInstance;

                const initSwiper = (autoplayOption) => {
                    swiperInstance = new Swiper(`.time-line-component-${index + 1} .time-line-carousel`, {
                        navigation: {
                            nextEl: `.time-line-component-${index + 1} .swiper-button-next`,
                            prevEl: `.time-line-component-${index + 1} .swiper-button-prev`,
                        },
                        thumbs: {
                            swiper: thumbsSwiper,
                        },
                        effect: 'slide',
                        loop: true,
                        autoplay: autoplayOption,
                        initialSlide: total - 1
                    });
                };

                initSwiper(false);

                const checkVisibility = () => {
                    const rect = $(this)[0].getBoundingClientRect();
                    const windowHeight = window.innerHeight || document.documentElement.clientHeight;
                    if (rect.top < windowHeight && rect.bottom > 0) {
                        swiperInstance.destroy(false);
                        initSwiper(isAutoplay ? {
                            delay: delayVal,
                            stopOnLastSlide: false,
                            disableOnInteraction: false,
                        } : false);
                        $(window).off('scroll', checkVisibility);
                    }
                };

                $(window).on('scroll', checkVisibility);

                checkVisibility();
            });
        }
    });
}
