/**
 * Awards And Cert Component组件交互
 * @constructor
 */

import AnniversaryCarousel from "../../anniversary-carousel";

export function SustainabilityComponent() {
    $(() => {
        if ($('.sustainability-component').length > 0) {
            // 移动端轮播
            if (window.outerWidth < 1024) {
                const $carousel = $('.sustainability-component .sustainability-carousel');
                const autoplayVal = $carousel.data('autoplay')
                const delayVal = $carousel.data('delay') * 1000;
                // eslint-disable-next-line no-new
                new AnniversaryCarousel({
                    el: '.sustainability-carousel',
                    autoplay: autoplayVal,
                    delay: delayVal
                })
            }

            // 当前组件前的标题组件 在移动端隐藏，PC端显示
            const handlePrevTitle = () => {
                const $prev = $('.sustainability-component').prev();
                if ($prev.hasClass('common-title-component')) {
                    if (window.outerWidth < 1024) {
                        $prev.find('.common-title-box').hide();
                    } else {
                        $prev.find('.common-title-box').show();
                    }
                }
            }
            handlePrevTitle();
            $(window).resize(() => {
                handlePrevTitle();
            })
        }
    })
}
