import './index.less'
import { BannerCarouselComponent } from "./sections/banner-carousel-component";
import { AnchorNavComponent } from "./sections/anchor-nav-component";
import { CommonTitleComponent } from "./sections/common-title-component";
import { AwardsAndCertComponent } from "./sections/awards-and-cert-component";
import { SustainabilityComponent } from "./sections/sustainability-component";
import { TimeLineComponent } from "./sections/time-line-component";
import Slideshow from './sections/slide-swiper.js'
import { AboutUsGAEvent } from "./page.about-us-ga"

// 编辑环境模式
if (window.Shopify && window.Shopify.designMode) {
    document.querySelector('body').classList.add('shopify-edit-mode');
}
$(document).ready(function() {
    let params = {
        autoplay: $(".about-us-page .slide-swiper .slide-swiper-container").attr("data-autoplay") === "true" ? true : false,
        speed: Number($(".about-us-page .slide-swiper .slide-swiper-container").attr("data-speed")) || 8
    }

    new Slideshow(document.querySelector('.about-us-page .slide-swiper-container'), params)
})

BannerCarouselComponent()
AnchorNavComponent();
CommonTitleComponent();
AwardsAndCertComponent();
SustainabilityComponent();
TimeLineComponent();
AboutUsGAEvent();
